"""
Traffic state for every road segment.

IMPORTANT - data provenance
---------------------------
MASAR V1 is NOT connected to any live traffic feed. Every vehicle count is a
*simulated, user-defined input*:
  * "none"      - no data entered; treated as 0 vehicles (free flow)
  * "user"      - typed in by the operator
  * "simulated" - generated by the random scenario generator (seeded)
  * "scenario"  - loaded from a saved scenario file
Capacity is an *estimate* (lanes x length / vehicle spacing) unless the user
overrides it; free-flow speed comes from the OSM maxspeed tag or a default
for the road type. Each value carries its source so the UI can label it.
"""
from __future__ import annotations

import copy
import json
import math
from dataclasses import dataclass, asdict, field
from pathlib import Path

import numpy as np
import pandas as pd

from . import cost_function as cf
from .graph_manager import RoadNetwork, haversine_m

MAX_VEHICLES = 100_000
MAX_SPEED_KPH = 150.0
MIN_SPEED_KPH = 1.0
MAJOR_ROADS = ("trunk", "primary", "secondary")

# Load is vehicles / capacity. These are what-if patterns, not measurements.
PRESETS = {
    "empty": {"label": "Empty roads", "hint": "No vehicles anywhere"},
    "calm": {"label": "Quiet day", "hint": "Light traffic everywhere", "major": 0.25, "minor": 0.15, "spread": 0.10},
    "busy": {"label": "Busy afternoon", "hint": "Main roads fill up", "major": 0.70, "minor": 0.35, "spread": 0.15},
    "rush_hour": {"label": "Rush hour", "hint": "Main roads jammed, side streets busy",
                  "major": 1.05, "minor": 0.55, "spread": 0.18},
    "downtown": {"label": "Downtown jam", "hint": "Worst at the centre, clear at the edges",
                 "major": 1.25, "minor": 1.05, "spread": 0.10, "downtown": True},
}


@dataclass
class CapacityParams:
    vehicle_spacing_m: float = 20.0   # road length one vehicle "occupies" when the road is at capacity

    def estimate(self, length_m: float, lanes: int) -> int:
        spacing = max(float(self.vehicle_spacing_m), 1.0)
        return max(1, int(round(max(lanes, 1) * max(length_m, 0.0) / spacing)))


@dataclass
class EdgeTraffic:
    vehicles: int
    capacity: int
    free_speed_kph: float
    closed: bool = False
    vehicles_source: str = "none"
    capacity_source: str = "estimated"
    speed_source: str = "osm/default"


def validate_vehicles(value) -> int:
    try:
        f = float(value)
    except (TypeError, ValueError):
        raise ValueError(f"Vehicle count must be a number, got {value!r}")
    if math.isnan(f) or math.isinf(f):
        raise ValueError("Vehicle count must be a finite number")
    if f < 0:
        raise ValueError("Vehicle count cannot be negative")
    if f != int(f):
        raise ValueError("Vehicle count must be a whole number")
    if f > MAX_VEHICLES:
        raise ValueError(f"Vehicle count above {MAX_VEHICLES} is not plausible for one segment")
    return int(f)


def validate_capacity(value) -> int:
    try:
        f = float(value)
    except (TypeError, ValueError):
        raise ValueError(f"Capacity must be a number, got {value!r}")
    if math.isnan(f) or math.isinf(f) or f < 0:
        raise ValueError("Capacity must be a non-negative finite number")
    return int(round(f))


def validate_speed(value) -> float:
    try:
        f = float(value)
    except (TypeError, ValueError):
        raise ValueError(f"Speed must be a number, got {value!r}")
    if math.isnan(f) or not (MIN_SPEED_KPH <= f <= MAX_SPEED_KPH):
        raise ValueError(f"Free-flow speed must be between {MIN_SPEED_KPH} and {MAX_SPEED_KPH} km/h")
    return f


class TrafficManager:
    def __init__(self, network: RoadNetwork, capacity_params: CapacityParams | None = None):
        self.network = network
        self.capacity_params = capacity_params or CapacityParams()
        self.version = 0          # increments on every change (used to trigger re-routing)
        self.state: dict[str, EdgeTraffic] = {}
        self.reset_all()

    # ------------------------------------------------------------- defaults
    def _default(self, edge_id: str) -> EdgeTraffic:
        d = self.network.edge_data(edge_id)
        return EdgeTraffic(
            vehicles=0,
            capacity=self.capacity_params.estimate(d["length"], d.get("lanes", 1)),
            free_speed_kph=float(d["speed_kph"]),
            closed=False,
            vehicles_source="none",
            capacity_source="estimated",
            speed_source=d.get("speed_source", "osm/default"),
        )

    def _bump(self):
        self.version += 1

    def reset_all(self) -> None:
        self.state = {eid: self._default(eid) for eid in self.network.edge_ids()}
        self._bump()

    def reset_vehicles(self) -> None:
        for t in self.state.values():
            t.vehicles, t.vehicles_source = 0, "none"
        self._bump()

    def reset_edge(self, edge_id: str) -> None:
        self.state[edge_id] = self._default(edge_id)
        self._bump()

    def set_vehicle_spacing(self, spacing_m: float) -> None:
        """Change the capacity model; re-estimates every capacity the user has not overridden."""
        spacing_m = max(float(spacing_m), 1.0)
        if abs(spacing_m - self.capacity_params.vehicle_spacing_m) < 1e-9:
            return
        self.capacity_params.vehicle_spacing_m = spacing_m
        for eid, t in self.state.items():
            if t.capacity_source == "estimated":
                d = self.network.edge_data(eid)
                t.capacity = self.capacity_params.estimate(d["length"], d.get("lanes", 1))
        self._bump()

    # -------------------------------------------------------------- setters
    def _check(self, edge_id: str) -> EdgeTraffic:
        if edge_id not in self.state:
            raise KeyError(f"Unknown road segment id {edge_id!r}")
        return self.state[edge_id]

    def set_vehicles(self, edge_id: str, vehicles, source: str = "user") -> None:
        t = self._check(edge_id)
        t.vehicles = validate_vehicles(vehicles)
        t.vehicles_source = source
        self._bump()

    def set_capacity(self, edge_id: str, capacity) -> None:
        t = self._check(edge_id)
        t.capacity = validate_capacity(capacity)
        t.capacity_source = "user"
        self._bump()

    def set_free_speed(self, edge_id: str, speed_kph) -> None:
        t = self._check(edge_id)
        t.free_speed_kph = validate_speed(speed_kph)
        t.speed_source = "user"
        self._bump()

    def set_closed(self, edge_id: str, closed: bool) -> None:
        self._check(edge_id).closed = bool(closed)
        self._bump()

    def update_edge(self, edge_id: str, vehicles=None, capacity=None, free_speed_kph=None, closed=None) -> None:
        """Validate everything first, then apply atomically."""
        t = self._check(edge_id)
        new = copy.copy(t)
        if vehicles is not None:
            new.vehicles, new.vehicles_source = validate_vehicles(vehicles), "user"
        if capacity is not None:
            new.capacity, new.capacity_source = validate_capacity(capacity), "user"
        if free_speed_kph is not None:
            new.free_speed_kph, new.speed_source = validate_speed(free_speed_kph), "user"
        if closed is not None:
            new.closed = bool(closed)
        self.state[edge_id] = new
        self._bump()

    # -------------------------------------------------------------- metrics
    def get(self, edge_id: str) -> EdgeTraffic:
        return self._check(edge_id)

    def ratio(self, edge_id: str) -> float:
        t = self.state[edge_id]
        return cf.congestion_ratio(t.vehicles, t.capacity)

    def travel_time(self, edge_id: str, params: cf.CostParams) -> float:
        t = self.state[edge_id]
        d = self.network.edge_data(edge_id)
        return cf.edge_travel_time(d["length"], t.free_speed_kph, t.vehicles, t.capacity, params)

    def free_time(self, edge_id: str, params: cf.CostParams) -> float:
        t = self.state[edge_id]
        return cf.free_flow_time(self.network.edge_data(edge_id)["length"], t.free_speed_kph, params)

    def speed_kph(self, edge_id: str, params: cf.CostParams) -> float:
        t = self.state[edge_id]
        return cf.estimated_speed_kph(t.free_speed_kph, t.vehicles, t.capacity, params)

    def metrics(self, edge_id: str, params: cf.CostParams) -> dict:
        t = self.state[edge_id]
        d = self.network.edge_data(edge_id)
        r = cf.congestion_ratio(t.vehicles, t.capacity)
        return {
            "edge_id": edge_id,
            "name": self.network.display_name(d),
            "highway": d.get("highway", ""),
            "oneway": d.get("oneway", False),
            "length_m": d["length"],
            "vehicles": t.vehicles,
            "capacity": t.capacity,
            "congestion_pct": 100.0 * r,
            "level": cf.congestion_level(r),
            "free_speed_kph": t.free_speed_kph,
            "avg_speed_kph": cf.estimated_speed_kph(t.free_speed_kph, t.vehicles, t.capacity, params),
            "travel_time_s": cf.edge_travel_time(d["length"], t.free_speed_kph, t.vehicles, t.capacity, params),
            "closed": t.closed,
            "vehicles_source": t.vehicles_source,
            "capacity_source": t.capacity_source,
            "speed_source": t.speed_source,
        }

    def dataframe(self, params: cf.CostParams, edge_ids: list[str] | None = None) -> pd.DataFrame:
        ids = edge_ids if edge_ids is not None else list(self.state)
        return pd.DataFrame([self.metrics(e, params) for e in ids])

    def summary(self) -> dict:
        ratios = np.array([cf.congestion_ratio(t.vehicles, t.capacity) for t in self.state.values()])
        with_data = sum(1 for t in self.state.values() if t.vehicles_source != "none")
        return {
            "segments": len(self.state),
            "segments_with_input": with_data,
            "total_vehicles": int(sum(t.vehicles for t in self.state.values())),
            "high": int((ratios >= cf.MODERATE_MAX).sum()),
            "moderate": int(((ratios >= cf.LOW_MAX) & (ratios < cf.MODERATE_MAX)).sum()),
            "closed": sum(1 for t in self.state.values() if t.closed),
        }

    # ---------------------------------------------------- simulated scenarios
    def apply_random_scenario(self, seed: int = 42, mean_load: float = 0.45, spread: float = 0.35,
                              major_road_boost: float = 0.25) -> None:
        """Fill every segment with SYNTHETIC vehicle counts (labelled 'simulated').

        Load ratio ~ clipped normal(mean_load (+boost on primary/secondary/trunk), spread).
        This is a reproducible what-if scenario, not a measurement.
        """
        rng = np.random.default_rng(seed)
        for eid, t in self.state.items():
            hw = self.network.edge_data(eid).get("highway", "")
            boost = major_road_boost if hw.split("_")[0] in ("trunk", "primary", "secondary") else 0.0
            ratio = float(np.clip(rng.normal(mean_load + boost, spread), 0.0, 1.6))
            t.vehicles = int(round(ratio * t.capacity))
            t.vehicles_source = "simulated"
        self._bump()

    def fluctuate(self, rng: np.random.Generator, volatility: float = 0.15) -> None:
        """Random-walk step used by experiment mode (same seed => same evolution)."""
        ids = list(self.state)
        noise = rng.normal(0.0, volatility, size=len(ids))
        for eid, n in zip(ids, noise):
            t = self.state[eid]
            if t.vehicles > 0:
                t.vehicles = int(max(0, round(t.vehicles * (1.0 + n))))
                t.vehicles_source = "simulated"
        self._bump()

    def apply_preset(self, name: str, seed: int = 42) -> None:
        """Fill the map with a named, reproducible what-if pattern (labelled 'simulated')."""
        if name not in PRESETS:
            raise ValueError(f"Unknown traffic preset {name!r}")
        if name == "empty":
            self.reset_vehicles()
            return
        preset = PRESETS[name]
        rng = np.random.default_rng(seed)
        clat, clon = self.network.center()
        s, w, _, _ = self.network.bounds()
        reach = max(float(haversine_m(clat, clon, s, w)), 1.0)
        for eid, t in self.state.items():
            d = self.network.edge_data(eid)
            major = d.get("highway", "").split("_")[0] in MAJOR_ROADS
            load = preset["major"] if major else preset["minor"]
            if preset.get("downtown"):
                lat, lon = d["coords"][len(d["coords"]) // 2]
                closeness = 1.0 - min(float(haversine_m(lat, lon, clat, clon)) / (reach * 0.7), 1.0)
                load = 0.15 + load * closeness ** 1.2
            ratio = float(np.clip(rng.normal(load, preset["spread"]), 0.0, 1.6))
            t.vehicles = int(round(ratio * t.capacity))
            t.vehicles_source = "simulated"
        self._bump()

    def set_load(self, edge_ids: list[str], ratio: float, source: str = "user") -> None:
        """Set each segment to `ratio` x its own capacity."""
        ratio = float(ratio)
        if math.isnan(ratio) or math.isinf(ratio) or ratio < 0:
            raise ValueError("Traffic load must be a non-negative number")
        for eid in edge_ids:
            t = self._check(eid)
            t.vehicles = validate_vehicles(round(ratio * max(t.capacity, 1)))
            t.vehicles_source = source
        self._bump()

    def set_total(self, edge_ids: list[str], total, source: str = "user") -> None:
        """Share `total` vehicles between segments in proportion to their capacity."""
        total = validate_vehicles(total)
        if not edge_ids:
            return
        caps = [max(self._check(e).capacity, 1) for e in edge_ids]
        exact = [total * c / sum(caps) for c in caps]
        counts = [int(x) for x in exact]
        by_remainder = sorted(range(len(exact)), key=lambda i: exact[i] - counts[i], reverse=True)
        for i in by_remainder[:total - sum(counts)]:
            counts[i] += 1
        for eid, n in zip(edge_ids, counts):
            t = self.state[eid]
            t.vehicles, t.vehicles_source = n, source
        self._bump()

    def pulse(self, rng: np.random.Generator, base: dict[str, int], volatility: float = 0.15) -> None:
        """Vary traffic around `base` counts. Unlike `fluctuate` it cannot drift away from them."""
        noise = rng.normal(0.0, volatility, size=len(base))
        for (eid, count), n in zip(base.items(), noise):
            if count > 0:
                t = self.state[eid]
                t.vehicles = int(max(0, round(count * (1.0 + n))))
                t.vehicles_source = "simulated"
        self._bump()

    def band_counts(self, edge_ids: list[str] | None = None) -> dict[str, int]:
        counts = dict.fromkeys(cf.BANDS, 0)
        for eid in (edge_ids if edge_ids is not None else self.state):
            t = self.state[eid]
            counts[cf.traffic_band(cf.congestion_ratio(t.vehicles, t.capacity))] += 1
        return counts

    # ------------------------------------------------------------ snapshots
    def snapshot(self) -> dict[str, EdgeTraffic]:
        return {k: copy.copy(v) for k, v in self.state.items()}

    def restore(self, snapshot: dict[str, EdgeTraffic]) -> None:
        self.state = {k: copy.copy(v) for k, v in snapshot.items()}
        self._bump()

    def clone(self) -> "TrafficManager":
        other = TrafficManager.__new__(TrafficManager)
        other.network = self.network
        other.capacity_params = copy.copy(self.capacity_params)
        other.version = self.version
        other.state = {k: copy.copy(v) for k, v in self.state.items()}
        return other

    def to_scenario(self, name: str = "scenario", only_changed: bool = True) -> dict:
        entries = {}
        for eid, t in self.state.items():
            default = self._default(eid)
            if only_changed and asdict(t) == asdict(default):
                continue
            entries[eid] = asdict(t)
        return {"name": name, "format": "masar-scenario-v1",
                "note": "Simulated / user-defined traffic inputs - not measured data.",
                "capacity_params": asdict(self.capacity_params), "edges": entries}

    def load_scenario(self, data: dict) -> tuple[int, int]:
        """Returns (applied, skipped). Unknown edge ids are skipped (other map area)."""
        if data.get("format") != "masar-scenario-v1":
            raise ValueError("Not a MASAR scenario file")
        self.reset_all()
        applied = skipped = 0
        for eid, vals in data.get("edges", {}).items():
            if eid not in self.state:
                skipped += 1
                continue
            t = EdgeTraffic(
                vehicles=validate_vehicles(vals.get("vehicles", 0)),
                capacity=validate_capacity(vals.get("capacity", self.state[eid].capacity)),
                free_speed_kph=validate_speed(vals.get("free_speed_kph", self.state[eid].free_speed_kph)),
                closed=bool(vals.get("closed", False)),
                vehicles_source="scenario" if vals.get("vehicles_source", "none") != "none" else "none",
                capacity_source=vals.get("capacity_source", "estimated"),
                speed_source=vals.get("speed_source", "osm/default"),
            )
            self.state[eid] = t
            applied += 1
        self._bump()
        return applied, skipped

    def save_scenario(self, path: Path, name: str) -> None:
        Path(path).write_text(json.dumps(self.to_scenario(name), indent=1, ensure_ascii=False), encoding="utf-8")

    def load_scenario_file(self, path: Path) -> tuple[int, int]:
        return self.load_scenario(json.loads(Path(path).read_text(encoding="utf-8")))
